import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"18、【蠱】 巽下艮上","description":"周易口訣義 - 18、【蠱】 巽下艮上","frontmatter":{"title":"18、【蠱】 巽下艮上","description":"周易口訣義 - 18、【蠱】 巽下艮上"},"headers":[],"relativePath":"classics/koujueyi/020.md","filePath":"classics/koujueyi/020.md"}'),r={name:"classics/koujueyi/020.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_18、【蠱】-巽下艮上" tabindex="-1">18、【蠱】 巽下艮上 <a class="header-anchor" href="#_18、【蠱】-巽下艮上" aria-label="Permalink to “18、【蠱】 巽下艮上”">​</a></h1><p>彖曰：「蠱」，剛上而柔下，巽而止，蠱。蠱元亨，而天下治也。「利涉大川」，往有事也。「先甲三日，後甲三日」，終則有始，天行也。</p><p>象曰：山下有風，蠱，君子以振民育德。</p><p>初六：幹父之蠱，有子，考無咎，厲終吉。</p><p>象曰：「幹父之蠱」，意承考也。</p><p>九二：幹母之蠱，不可貞。</p><p>象曰：「幹母之蠱」，得中道也。</p><p>九三：幹父之蠱，小有悔，無大咎。</p><p>象曰：「幹父之蠱」，終無咎也。</p><p>六四，裕父之蠱，往見吝。</p><p>象曰：「裕父之蠱」，往未得也。</p><p>六五，幹父之蠱，用譽。</p><p>象曰：「幹父用譽」，承以德也。</p><p>上九，不事王侯，高尚其事。</p><p>象曰：「不事王侯」，志可則也。</p><p>解讀</p><p>蠱，元亨，利涉大川。「蠱」，事也，謂創制立法有為之事也。教化必大通，故曰「元亨」也；立法施令大行，故曰「利涉大川」也。「先甲三日，後甲三日」者，甲創制之始，故創令立法先三日，恐人未曉，殷勤告示雲「後甲三日」。如此再三，丁寧宣佈，此後犯者必誅，使民無怨，乃得「無咎」也。象曰「山下有風，蠱」者，先儒雲：「蠱，惑也。」按春秋「女惑男，風落山謂之蠱」。既有惑亂，當以教事制之，非是蠱訓為「事」，亦猶風行山下，惑亂萬物，奸在人間，惑亂眾庶，故以教法齊之也。「君子以振民育德」者，君子以振濟人民，象風之散佈；育養其德，象山之安靜也。</p><p>「初六，幹父之蠱，有子，考無咎，厲終吉」者，考是父，妣是母，此即先儒通稱也。初六處事之初，即能幹成父事，故曰「幹父之蠱」也；子能幹了家事，父又何憂？父能無慮，故曰「有子，考無咎」也。治家之初，恐有危厲，而能幹濟家事，克終父命，故曰「厲終吉」也。</p><p>「九二，幹母之蠱，不可貞」者，以陽居陰，而又處中，女人以內為本，故曰「幹母之蠱」也。女人之性情多狠戾，故不可全為正，故云「不可貞」。</p><p>「九三，幹父之蠱，小有悔，無大咎」者，以陽居陽，處一家之剛正，能幹濟父事，故曰「幹父之蠱」；為無其應，即不可以行，故「小有悔吝」，能堪家事，即「終無大咎」矣。</p><p>「六四，裕父之蠱，往見吝」者，「裕」，寬也；以陰得位，寬猛得宜，即是能容「裕父之蠱」也。亦是無應而行，人所不親，故曰「往見吝」也。</p><p>「六五幹父之蠱，用譽」者，幹事得至尊位，是能幹辦父事，承先之德，故有美譽於外。孝經雲「立身行道，揚名於後世，以顯父母」是也。</p><p>「上九：不事王侯，高尚其事」者，最處事上，是能高尚其名，不羈其身，但可清虛守道，不事君侯，眾多敬仰，故曰「高尚其事」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
